// ============ CONFIG — Ativar contrato na RESOLUTTO (espelho das bases de origem) ============
// Regra: O.S. de "Ativação Link Normal" FINALIZADA numa base de origem + contrato dessa O.S. ATIVO na origem
//        -> o cliente de mesmo CNPJ/CPF na RESOLUTTO tem o seu ÚNICO pré-contrato (status P) ativado.
const cfg = {
  // NENHUM = não faz nada | SIMULAR = mostra o que faria (padrão) | REAL = ativa de verdade (só no n8n de PRODUÇÃO)
  MODO: 'SIMULAR',

  // Base de origem -> assuntos que disparam (Ativação Link Normal). A RESOLUTTO é sempre o destino.
  ORIGENS: {
    '4B':  [16],
    PONTO: [4],
    CACTA: [43],
    BUZZ:  [45],
  },

  // Olha as O.S. finalizadas nas últimas N horas (data_fechamento). O que já foi resolvido não é relido (memória do workflow).
  JANELA_HORAS: 48,
  MAX_OS_RODADA: 200,          // O.S. lidas por rodada (as mais antigas primeiro)
  MAX_ATIVACOES_RODADA: 10,    // trava: contratos ativados por rodada

  STATUS_ORIGEM_OK: ['A'],     // status do contrato na origem que libera a ativação
  STATUS_PRE: ['P'],           // pré-contrato na RESOLUTTO (o único que pode ser ativado)
  STATUS_ATIVO: ['A'],         // já ativo na RESOLUTTO = nada a fazer

  IGNORAR_DOCS: [],            // CNPJ/CPF (só dígitos) que nunca são ativados automaticamente
  TZ: 'America/Sao_Paulo',
};

const local = (d) => d.toLocaleString('sv-SE', { timeZone: cfg.TZ }).replace('T', ' ');
const agora = new Date();
cfg.agora = local(agora);
cfg.desde = local(new Date(agora.getTime() - cfg.JANELA_HORAS * 3600000));

// Corpo da leitura das O.S. finalizadas, por base (1 chamada por base).
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(String).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
cfg.corpoOS = {};
for (const [b, assuntos] of Object.entries(cfg.ORIGENS)) {
  const grid = cfg.MODO === 'NENHUM'
    ? [{ TB: 'su_oss_chamado.id', OP: '=', P: '0' }]
    : [filtroIds('su_oss_chamado.id_assunto', assuntos),
       { TB: 'su_oss_chamado.status', OP: '=', P: 'F' },
       { TB: 'su_oss_chamado.data_fechamento', OP: '>=', P: cfg.desde }];
  cfg.corpoOS[b] = { qtype: 'su_oss_chamado.id', query: '0', oper: '>', page: '1', rp: '1000',
    sortname: 'su_oss_chamado.id', sortorder: 'asc', grid_param: JSON.stringify(grid) };
}
return [{ json: { cfg } }];

// ---- comum (inserido no início dos nós de código pelo gerar.py) ----
function parseTolerante(v) {
  if (v && typeof v === 'object' && v.data === undefined) return v;
  const txt = v && typeof v === 'object' ? v.data : v;
  const limpo = String(txt || '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(limpo); } catch (e) { return { erro_parse: 'JSON inválido: ' + e.message }; }
}
const msgErro = (e) => typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);
function falhou(r) {
  if (!r) return 'sem resposta';
  if (r.erro_parse) return r.erro_parse;
  if (r.error) return msgErro(r.error);
  if (r.type === 'error') return 'IXC recusou: ' + String(r.message || JSON.stringify(r)).slice(0, 300);
  if (!Number.isFinite(Number(r.total))) return 'resposta inesperada (sem "total"): ' + JSON.stringify(r).slice(0, 200);
  if (Number(r.total) > 0 && !Array.isArray(r.registros)) return 'IXC informou ' + r.total + ' registros mas não mandou a lista';
  return '';
}
const regs = (r) => Array.isArray(r && r.registros) ? r.registros : [];
const digitos = (s) => String(s || '').replace(/\D/g, '');
const formatarDoc = (d) => d.length === 14 ? d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5')
  : d.length === 11 ? d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4') : d;
const filtroIds = (tb, ids) => {
  const v = [...new Set((ids || []).map(String).filter(x => /^\d+$/.test(x) && x !== '0'))];
  if (!v.length) return { TB: tb, OP: '=', P: '0' };
  return v.length === 1 ? { TB: tb, OP: '=', P: v[0] } : { TB: tb, OP: 'IN', P: v.join(',') };
};
const corpoIds = (tab, campo, ids) => ({ qtype: tab + '.id', query: '0', oper: '>', page: '1', rp: '5000',
  sortname: tab + '.id', sortorder: 'asc', grid_param: JSON.stringify([filtroIds(tab + '.' + campo, ids)]) });
const VAZIO = (tab) => ({ qtype: tab + '.id', query: '0', oper: '=', page: '1', rp: '1' });
// Campo do contrato na O.S.: o IXC usa id_contrato_kit (confirmado no painelixc); id_contrato fica de reserva.
const CAMPOS_CONTRATO_OS = ['id_contrato_kit', 'id_contrato'];
// ---- fim do comum ----

// Junta as O.S. finalizadas das bases de origem, tira as já resolvidas e prepara a leitura de contratos e clientes.
const cfg = $('Config').first().json.cfg;
const BASES = Object.keys(cfg.ORIGENS);
const st = $getWorkflowStaticData('global');
st.feitos = st.feitos || {};
const limite = Date.now() - (cfg.JANELA_HORAS + 24) * 3600000;
for (const k of Object.keys(st.feitos)) if (!(st.feitos[k] >= limite)) delete st.feitos[k];

const lista = [], erros = {}, campos = {};
let jaFeitas = 0;
if (cfg.MODO !== 'NENHUM') for (const b of BASES) {
  const r = parseTolerante($('OS ' + b).first().json);
  const e = falhou(r);
  if (e) { erros[b] = 'leitura das O.S.: ' + e; continue; }
  const assuntos = cfg.ORIGENS[b].map(String);
  for (const o of regs(r)) {
    if (!campos[b]) campos[b] = Object.keys(o).filter(k => /contrato/i.test(k));
    // Conferência local (a API já filtrou; se algum filtro for ignorado pelo IXC, nada passa errado).
    if (String(o.status) !== 'F' || !assuntos.includes(String(o.id_assunto))) continue;
    if (String(o.data_fechamento || '') < cfg.desde) continue;
    if (st.feitos[b + ':' + o.id]) { jaFeitas++; continue; }
    const campo = CAMPOS_CONTRATO_OS.find(c => o[c] !== undefined);
    lista.push({ base: b, id_os: String(o.id), id_assunto: String(o.id_assunto), id_cliente: String(o.id_cliente || ''),
      id_contrato: campo ? String(o[campo] || '') : '', campo_contrato: campo || '', data_fechamento: String(o.data_fechamento || '') });
  }
}
lista.sort((a, b) => a.data_fechamento < b.data_fechamento ? -1 : a.data_fechamento > b.data_fechamento ? 1 : 0);
const cortadas = Math.max(0, lista.length - cfg.MAX_OS_RODADA);
const os = lista.slice(0, cfg.MAX_OS_RODADA);

const corpos = { contratos: {}, clientes: {} };
for (const b of BASES) {
  const da = os.filter(x => x.base === b);
  corpos.contratos[b] = da.length ? corpoIds('cliente_contrato', 'id', da.map(x => x.id_contrato)) : VAZIO('cliente_contrato');
  corpos.clientes[b] = da.length ? corpoIds('cliente', 'id', da.map(x => x.id_cliente)) : VAZIO('cliente');
}
return [{ json: { os, erros, campos, ja_feitas: jaFeitas, cortadas, corpos } }];

